css:
.d-table-column-filters{width:100%;max-width:430px;min-width:0;color:var(--ink);font:inherit;font-size:14px;line-height:1.5;overflow-wrap:anywhere}
.d-table-column-filters *,.d-table-column-filters *::before,.d-table-column-filters *::after{box-sizing:border-box}
.d-table-column-filters [hidden]{display:none!important}
.d-table-column-filters .d-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}
.d-table-column-filters .d-note{display:block;margin:8px 0 0;color:var(--muted);font-size:12px;min-height:1.5em}
.d-table-column-filters label{display:block;margin:8px 0}
.d-table-column-filters input,.d-table-column-filters select,.d-table-column-filters textarea,.d-table-column-filters button{font:inherit;color:inherit;max-width:100%;min-width:0}
.d-table-column-filters input:not([type=checkbox]):not([type=radio]),.d-table-column-filters select,.d-table-column-filters textarea{width:100%;padding:8px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper)}
.d-table-column-filters button{padding:6px 10px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper);cursor:pointer}
.d-table-column-filters button:disabled{opacity:.5;cursor:default}
.d-table-column-filters :focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.d-table-column-filters [aria-invalid=true]{border-color:var(--warn)!important}
.d-table-column-filters .d-scroll{max-width:100%;overflow:auto}
.d-table-column-filters table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}
.d-table-column-filters th,.d-table-column-filters td{padding:7px;border-bottom:1px solid var(--line);vertical-align:top}
.d-table-column-filters caption{text-align:left;font-weight:600;margin-bottom:8px}
.d-table-column-filters progress{width:100%;accent-color:var(--ink)}
.d-table-column-filters pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}
.d-table-column-filters h3,.d-table-column-filters p{margin:8px 0}
.d-table-column-filters [aria-pressed=true],.d-table-column-filters [aria-selected=true]{border-color:var(--ink);font-weight:650}
.d-table-column-filters .d-grow{flex:1;min-width:100px}
.d-table-column-filters summary{cursor:pointer;padding:6px 0}
.d-table-column-filters ul,.d-table-column-filters ol{padding-left:24px}

init:
root => {
 const q = selector => root.querySelector(selector);
 const qa = selector => [...root.querySelectorAll(selector)];
 const say = text => { const out = q('[data-out]'); if (out) out.textContent = text; };
 ((root,q,qa,say)=>{const apply=()=>{let count=0;qa('tbody tr').forEach(row=>{const match=row.cells[0].textContent.includes(q('[data-name]').value)&&(!q('[data-status]').value||row.cells[1].textContent===q('[data-status]').value);row.hidden=!match;if(match)count++;});say(count+' 条匹配');};q('[data-name]').oninput=apply;q('[data-status]').onchange=apply;q('[data-reset]').onclick=()=>{q('[data-name]').value='';q('[data-status]').value='';apply();};apply();})(root, q, qa, say);
}
